import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        try c.SetMinSum(m) {} catch { return; }
        uint256 before1;
        try c.MinSum() returns (uint256 __r) { before1 = __r; } catch { return; }
        bool depReverted;
        try c.Deposit{value: a}() { depReverted = false; } catch { depReverted = true; }
        uint256 mid1;
        try c.MinSum() returns (uint256 __r) { mid1 = __r; } catch { return; }
        bool colReverted;
        try c.Collect(b) { colReverted = false; } catch { colReverted = true; }
        uint256 after2;
        try c.MinSum() returns (uint256 __r) { after2 = __r; } catch { return; }
        assertTrue(before1 == m && mid1 == m && after2 == m);
    }

    function testFuzz_run(uint256 m, uint256 a, uint256 b) public {
        _run(m, a, b);
    }

    receive() external payable {}
}
